    {id:'corner-roast',name:'Corner Roast',suburb:'Fitzroy',cuisine:'Specialty coffee',kind:'Cafes',tags:['Coffee','Bakery'],image:'assets/coffee.jpg',dish:'Melbourne flat white',description:'Small-batch beans, a well-made flat white and a sunlit window seat. A proper neighbourhood ritual.',x:83,y:40,distance:'950 m',rating:'4.8',price:'$',dishPrice:5,rarity:'Everyday gem',xp:50}
