  let stored = {}; try { stored = JSON.parse(localStorage.getItem(STORAGE) || '{}'); } catch {}
  const valid = defaults();
  for (const key of Object.keys(valid)) { if (Array.isArray(valid[key]) ? Array.isArray(stored?.[key]) : typeof stored?.[key] === typeof valid[key]) valid[key] = stored[key]; }
  let state = {...valid,view:'explore',city:'Melbourne',category:'Everything',query:'',mode:'map',selected:null,route:null,zoom:1,pan:{x:0,y:0},player:{x:54,y:49},dexTab:'all',questTab:'all',partner:{tab:'overview',onboardingStep:0,draft:{}},communityTab:'leaderboard'};
  let lastFocus, toastTimer, modalKind;
