  function toast(message) { const el=$('#toast'); el.innerHTML=icon('check',18)+`<span>${esc(message)}</span>`; el.classList.add('visible'); clearTimeout(toastTimer); toastTimer=setTimeout(()=>el.classList.remove('visible'),3500); }
  function activity(text, xp=0) { state.activity.unshift({text,xp,date:'Just now'}); state.activity=state.activity.slice(0,15); state.xp+=xp; save(); }
  function go(view) { closeModal(); state.view=view; state.dexTab='all'; state.query=''; state.category='Everything'; location.hash=view; render(); window.scrollTo(0,0); }
